from pathlib import Path
import base64,datetime,hashlib,json,subprocess,os
name='xiaopang1117_v41_sg438_decode_sj10'
expected='7eefcf3aedcb80825833e6b47295689965905518e51823cab8bedecfad6374f3'
root=Path('/data/nfs_shared/xiaopang/v41_xllm_match_sglang_20261116')
info=json.loads(subprocess.check_output(['docker','inspect',name]))[0]
assert info['Id']==expected and info['State']['Running']
g=subprocess.run(['timeout','20','mthreads-gmi'],capture_output=True,text=True,timeout=25)
assert g.returncode==0 and 'No running processes found' in g.stdout, g.stdout
ports=subprocess.check_output(['ss','-ltnH'],text=True)
assert not any(':'+str(p)+' ' in ports for p in [35691,35692])
assert not (root/'diagnostics/e51_gather_gpu_v1').exists(), 'Existing test must be inspected, not restarted'
receipt={'at':datetime.datetime.now().astimezone().isoformat(),'container':name,'container_id':expected,'gpu':g.stdout,'ports':ports,'files':{}}
p=root/"scripts"/'validate_v41_gather_candidate_v1.py'
data=base64.b64decode('')
assert not p.exists() or p.read_bytes()==data
p.write_bytes(data)
receipt["files"][str(p)]={"size":len(data),"sha256":hashlib.sha256(data).hexdigest()}
p=root/"scripts"/'e51_gather_gpu_supervisor_v1.py'
data=base64.b64decode('')
assert not p.exists() or p.read_bytes()==data
p.write_bytes(data)
receipt["files"][str(p)]={"size":len(data),"sha256":hashlib.sha256(data).hexdigest()}
payload="""import subprocess,json,os
from pathlib import Path
out=Path('/expt/diagnostics/e51_gather_supervisor_v1.log')
with out.open('xb') as f:
 p=subprocess.Popen(['python3','/expt/scripts/e51_gather_gpu_supervisor_v1.py'],stdout=f,stderr=subprocess.STDOUT,start_new_session=True)
print(json.dumps({'pid':p.pid,'start_ticks':Path('/proc/%s/stat'%p.pid).read_text().split()[21]}))
"""
r=subprocess.run(['docker','exec','-i',name,'python3','-'],input=payload,capture_output=True,text=True,timeout=20)
receipt['launch_exit']=r.returncode;receipt['launch_stdout']=r.stdout;receipt['launch_stderr']=r.stderr
(root/'diagnostics/e51_gather_gpu_launch_v1.json').write_text(json.dumps(receipt,indent=2))
print(json.dumps({k:v for k,v in receipt.items() if k not in ['gpu','ports']},indent=2))
assert r.returncode==0
